<?php $assetEdit=null;foreach(records('asset') as $r)if($r['id']===(int)request('edit',0))$assetEdit=$r; ?>
<p>Thêm file .css/.js hoặc viết mã trực tiếp. Mã tùy chỉnh áp dụng ngoài website, không chạy trong trang quản trị. Chỉ dùng mã bạn tin tưởng.</p>
<?php if(request()->has('new')||$assetEdit):$assetValues=old()?:($assetEdit??['kind'=>'css','placement'=>'footer','position'=>10,'enabled'=>true]);?>
<form class="panel" method="post" enctype="multipart/form-data"><input type="hidden" name="_token" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=e($assetEdit['id']??0)?>"><div class="editor-heading"><h2><?=$assetEdit?'Sửa file':'Thêm file'?></h2><a href="<?=e(adminUrl('assets'))?>">← Danh sách</a></div><div class="settings-grid"><label>Tên file<input name="name" value="<?=e($assetValues['name']??'')?>" placeholder="custom-theme" maxlength="100"></label><label>Loại file<select name="kind"><option value="css" <?=($assetValues['kind']??'css')==='css'?'selected':''?>>CSS</option><option value="js" <?=($assetValues['kind']??'')==='js'?'selected':''?>>JavaScript</option></select></label><label>Vị trí JavaScript<select name="placement"><option value="footer" <?=($assetValues['placement']??'footer')==='footer'?'selected':''?>>Cuối trang</option><option value="head" <?=($assetValues['placement']??'')==='head'?'selected':''?>>Đầu trang</option></select></label><label>Thứ tự tải<input name="position" type="number" min="0" max="9999" value="<?=e($assetValues['position']??10)?>" required></label></div><label class="checkbox-label"><input type="checkbox" name="enabled" <?=!empty($assetValues['enabled'])?'checked':''?>> Bật file này trên website</label><label>Tải file CSS/JS (tùy chọn)<input name="asset_file" type="file" accept=".css,.js,text/css,text/javascript,application/javascript"></label><p class="muted">Tối đa 256 KB, UTF-8. File tải lên sẽ thay nội dung trong ô mã. CSS luôn tải ở đầu trang; JavaScript dùng defer. Khi lỗi, tắt file ở đây để khôi phục giao diện.</p><label>Nội dung mã<textarea class="code-editor" name="code" rows="18" spellcheck="false"><?=e($assetValues['code']??'')?></textarea></label><button name="action" value="asset_save">Lưu file ↗</button></form>
<?php else:$assetRows=records('asset');usort($assetRows,fn($a,$b)=>($a['position']<=>$b['position'])?:($a['id']<=>$b['id']));?><div class="toolbar"><p><?=count($assetRows)?> file</p><a class="button" href="<?=e(adminUrl('assets',['new'=>1]))?>">+ Thêm file CSS/JS</a></div><div class="panel table-wrap"><table><thead><tr><th>File</th><th>Vị trí / thứ tự</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($assetRows as $r):?><tr><td><strong><?=e($r['filename'])?></strong><small><?=e($r['name'])?> · <?=round(strlen($r['code'])/1024,1)?> KB</small></td><td><?=$r['kind']==='css'||$r['placement']==='head'?'Đầu trang':'Cuối trang'?> / <?=$r['position']?></td><td><span class="status"><?=!empty($r['enabled'])?'Đang bật':'Đã tắt'?></span></td><td><div class="actions"><a href="<?=e(adminUrl('assets',['edit'=>$r['id']]))?>">Sửa / bật tắt</a><?php if(!empty($r['enabled'])):?><a href="<?=e(custom_asset_url($r))?>" target="_blank" rel="noopener">Xem file ↗</a><?php endif;?><form method="post" onsubmit="return confirm('Xóa file tùy chỉnh?')"><input type="hidden" name="_token" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger" name="action" value="asset_delete">Xóa</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
